@app.cell(hide_code=True)
def _(mo, view):
    _note = "Deadline markers are stored observations; connecting lines are a visual guide, not extra evaluated deadlines. Every reference turn remains in the denominator."
    if view.value == "pause_probe":
        _note = "Controlled pause-probe rows are separate from the frozen main study. STOP contains no continuation and its gap labels the paired RESUME horizon, not a next activity edge. The same four stopped phrases repeat across pause settings. RESUME tests continuity across the requested RMS gap. All diagnostic turns stay in the denominator. Four examples per subgroup give coarse percentages; inspect counts and artifacts rather than reading this as a new leaderboard."
    elif view.value == "uncertainty":
        _note = "Solid lines are strict nominal success; dashed lines show possible (optimistic) success and dotted lines certain (conservative) success across stored reference-boundary uncertainty. These are timing sensitivity bounds, not confidence intervals. Early-active START failure is not equivalent to a slow or wholly missed response. All reference turns stay in every denominator."
    elif view.value == "frontier":
        _note = "Development only. Small markers show evaluated controllers; larger markers show the stored multi-objective Pareto set, which need not form a frontier in this two-axis projection. Stars are the selected operating point evaluated on development. Unreachable latency values are reported explicitly and not plotted as zero. No holdout sweep or retuning is performed."
    elif view.value == "conditions":
        _note = "Held-out condition subsets use the same frozen controller. Small denominators can make these comparisons unstable; unreachable quantiles and turn counts remain visible."
    elif view.value == "conditional":
        _note = "Successful-subset latency can look excellent when most turns fail. This diagnostic must be read beside the all-turn table and error counts below."
    elif view.value == "joint":
        _note = "Joint intact success requires both timely boundaries and a single unfragmented, unmerged episode. All reference turns remain in the denominator."
    mo.callout(mo.md(_note), kind="info")
    return


@app.cell(hide_code=True)
def _(boundary, mo, q, source_rows, view):
    condition_rows = []
    if view.value == "conditions":
        for _row in source_rows:
            condition_rows.append({"Detector": _row["backend"], "Condition": _row["condition"],
                "Turns": _row["metric"]["counts"]["turns"], f"{boundary.value} all-turn {q.value}": _row["quantile_status"],
                "False starts": _row["metric"]["counts"]["false_starts"],
                "Negative hours": _row["metric"]["negative_hours"],
                "False starts / negative hour": _row["metric"]["false_starts_per_negative_hour"],
                "Operational FP seconds": _row["metric"].get("operational_false_positive_s"),
                "Operational FP / negative time (%)": None if _row["metric"].get("operational_false_positive_fraction") is None else 100*_row["metric"]["operational_false_positive_fraction"]})
    mo.vstack([mo.md("## Condition statuses, including unreachable quantiles"),
               mo.ui.table(condition_rows, selection=None, page_size=12, show_data_types=False)]) if condition_rows else mo.md("")
    return (condition_rows,)


@app.cell(hide_code=True)
def _(mo, probe_comparison_rows, source_rows, view):
    probe_table_rows = probe_comparison_rows(source_rows) if view.value == "pause_probe" else []
    mo.vstack([mo.md("## Controlled-pause diagnostic: exact gaps, all-turn latency and errors"),
        mo.ui.table(probe_table_rows, selection=None, page_size=12, show_data_types=False,
                    freeze_columns_left=["Detector"]) if probe_table_rows else mo.md("No stored probe measurements.")]) if view.value == "pause_probe" else mo.md("")
    return (probe_table_rows,)


@app.cell(hide_code=True)
def _(boundary_results, comparison_rows, detectors, error_rows, mo, point_choice, view):
    paired_rows = comparison_rows(boundary_results, detectors.value, point_choice.value) if view.value != "pause_probe" else []
    count_rows = error_rows(boundary_results, detectors.value, point_choice.value) if view.value != "pause_probe" else []
    mo.vstack([
        mo.md("## Failure-aware latency: development and frozen holdout\nUnreachable means too few turns succeeded to reach that all-turn percentile. Undefined means no reference turns. Blank recall means unavailable, never zero. Controllers are identical across the paired splits."),
        mo.ui.table(paired_rows, page_size=12, selection=None, show_data_types=False,
                    freeze_columns_left=["Detector", "Split"]) if paired_rows else mo.md("No stored points for the selected detectors."),
        mo.md("## Error counts and exposure\nCounts can overlap. Known-negative hours are the false-start denominator. Operational FP duration reveals long false-active episodes hidden by low event counts. Small exposure and zero observed counts do not establish production reliability."),
        mo.ui.table(count_rows, page_size=12, selection=None, show_data_types=False,
                    freeze_columns_left=["Detector", "Split"]) if count_rows else mo.md("No error rows for this selection."),
    ]) if view.value != "pause_probe" else mo.md("")
    return count_rows, paired_rows


@app.cell(hide_code=True)
def _(boundary_results, count_rows, json, mo, paired_rows, point_choice, source_rows, view):
    mo.accordion({
        "Exact source rows and download": mo.vstack([
            mo.md("The JSON retains original fractions, complete controllers, errors, success counts and denominators. Displayed percentages and milliseconds are unit conversions only."),
            mo.download(data=json.dumps({"view": view.value, "operating_point": point_choice.value if view.value != "pause_probe" else "supplementary shared baseline; see source rows",
                "uncompressed_source_sha256": boundary_results.get("explorer_source_uncompressed_sha256", {}),
                "paired_rows": paired_rows, "count_rows": count_rows, "source_rows": source_rows},
                indent=2, allow_nan=False).encode(), filename="speech-boundary-selection.json", label="Download exact selected rows"),
            mo.md("```json\n"+json.dumps(source_rows[:3], indent=2)+"\n```"),
        ]),
        "Methodology and snapshot provenance": mo.md(
            "Embedded completed results; opening the notebook runs no detectors and fetches no benchmark data. SHA-256 below hashes uncompressed JSON bytes, identically for plain and gzip source files.\n\n"
            + "\n".join(f"- `{path}`: `{digest}`" for path, digest in boundary_results.get("explorer_source_uncompressed_sha256", {}).items())
            + f"\n\nManifest SHA-256: `{boundary_results.get('manifest_sha256', 'Not yet embedded')}`"
            + "\n\n```json\n"+json.dumps({"main_study": boundary_results.get("methodology", {}), "supplementary_probe": boundary_results.get("pause_probe", {}).get("methodology", {})}, indent=2)+"\n```"),
    })
    return


if __name__ == "__main__":
    app.run()
